mc(2, 'biofertilisers', 'Which of these is a fungal biofertiliser?', '<i>Glomus</i> (mycorrhiza)', ['<i>Anabaena</i>', '<i>Rhizobium</i>', '<i>Azotobacter</i>'], '<i>Glomus</i> forms mycorrhiza. Anabaena is a cyanobacterium and Rhizobium and Azotobacter are bacteria.');
asr(2, 'household', 'Curd is more nutritious than milk.', 'LAB increase the amount of vitamin B<sub>12</sub> in the curd.', 0, 'The vitamin gain is the reason for greater nutrition.');
asr(2, 'biogas', 'Cattle dung is used for the production of biogas in India.', 'It is available in large quantities.', 0, 'India has a large cattle population, so dung is easy to get.');
match(2, 'industrial', 'xm1', 'Microbe and the product', ['A. <i>Trichoderma polysporum</i>', 'B. <i>Monascus purpureus</i>', 'C. <i>Streptococcus</i>', 'D. <i>Penicillium notatum</i>'], ['p. Penicillin', 'q. Streptokinase', 'r. Statins', 's. Cyclosporin A'], 'A-s, B-r, C-q, D-p', ['A-r, B-s, C-q, D-p', 'A-s, B-r, C-p, D-q', 'A-q, B-r, C-s, D-p'], 'Cyclosporin A is from Trichoderma, statins from Monascus, streptokinase from Streptococcus and penicillin from Penicillium.');

